-- Initial AgroPilot schema. Apply with `npm run db:deploy`.
CREATE TYPE "UserRole" AS ENUM ('PRODUCER', 'TECHNICIAN', 'ADMIN');
CREATE TYPE "CropStatus" AS ENUM ('ACTIVE', 'HARVESTED', 'CANCELLED');
CREATE TYPE "DiagnosisStatus" AS ENUM ('PROCESSING', 'COMPLETED', 'FAILED', 'REVIEW_REQUIRED');
CREATE TYPE "RecommendationCategory" AS ENUM ('CLIMATE', 'HEALTH', 'IRRIGATION', 'NUTRITION', 'MARKET');
CREATE TYPE "Priority" AS ENUM ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL');
CREATE TYPE "RecommendationStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED', 'COMPLETED');
CREATE TYPE "AnalysisStatus" AS ENUM ('PROCESSING', 'COMPLETED', 'FAILED');
CREATE TYPE "MessageRole" AS ENUM ('USER', 'ASSISTANT', 'SYSTEM');

CREATE TABLE "User" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "UserRole" NOT NULL DEFAULT 'PRODUCER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "RefreshToken" ("id" UUID NOT NULL, "tokenHash" TEXT NOT NULL, "userId" UUID NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "RefreshToken_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "RefreshToken_tokenHash_key" ON "RefreshToken"("tokenHash"); CREATE INDEX "RefreshToken_userId_idx" ON "RefreshToken"("userId");
CREATE TABLE "Farm" ("id" UUID NOT NULL, "ownerId" UUID NOT NULL, "name" TEXT NOT NULL, "province" TEXT NOT NULL, "canton" TEXT NOT NULL, "latitude" DOUBLE PRECISION, "longitude" DOUBLE PRECISION, "totalAreaHa" DOUBLE PRECISION, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Farm_pkey" PRIMARY KEY ("id")); CREATE INDEX "Farm_ownerId_idx" ON "Farm"("ownerId");
CREATE TABLE "Plot" ("id" UUID NOT NULL, "farmId" UUID NOT NULL, "name" TEXT NOT NULL, "areaHa" DOUBLE PRECISION, "soilType" TEXT, "irrigationType" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Plot_pkey" PRIMARY KEY ("id")); CREATE INDEX "Plot_farmId_idx" ON "Plot"("farmId");
CREATE TABLE "Crop" ("id" UUID NOT NULL, "plotId" UUID NOT NULL, "cropType" TEXT NOT NULL, "variety" TEXT, "sowingDate" TIMESTAMP(3), "expectedHarvestDate" TIMESTAMP(3), "growthStage" TEXT, "status" "CropStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Crop_pkey" PRIMARY KEY ("id")); CREATE INDEX "Crop_plotId_idx" ON "Crop"("plotId");
CREATE TABLE "Diagnosis" ("id" UUID NOT NULL, "cropId" UUID NOT NULL, "imageUrl" TEXT NOT NULL, "symptoms" TEXT, "status" "DiagnosisStatus" NOT NULL DEFAULT 'COMPLETED', "finding" TEXT NOT NULL, "confidence" DOUBLE PRECISION NOT NULL, "explanation" TEXT NOT NULL, "requiresTechnicalReview" BOOLEAN NOT NULL DEFAULT false, "evidence" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Diagnosis_pkey" PRIMARY KEY ("id")); CREATE INDEX "Diagnosis_cropId_idx" ON "Diagnosis"("cropId");
CREATE TABLE "Analysis" ("id" UUID NOT NULL, "cropId" UUID NOT NULL, "status" "AnalysisStatus" NOT NULL DEFAULT 'COMPLETED', "analysisType" TEXT NOT NULL, "summary" TEXT NOT NULL, "agentResults" JSONB NOT NULL, "generatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Analysis_pkey" PRIMARY KEY ("id")); CREATE INDEX "Analysis_cropId_idx" ON "Analysis"("cropId");
CREATE TABLE "Recommendation" ("id" UUID NOT NULL, "cropId" UUID NOT NULL, "category" "RecommendationCategory" NOT NULL, "title" TEXT NOT NULL, "summary" TEXT NOT NULL, "priority" "Priority" NOT NULL, "confidence" DOUBLE PRECISION NOT NULL, "explanation" TEXT NOT NULL, "evidence" JSONB NOT NULL, "actions" JSONB NOT NULL, "requiresApproval" BOOLEAN NOT NULL DEFAULT true, "status" "RecommendationStatus" NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Recommendation_pkey" PRIMARY KEY ("id")); CREATE INDEX "Recommendation_cropId_status_idx" ON "Recommendation"("cropId", "status");
CREATE TABLE "WeeklyPlan" ("id" UUID NOT NULL, "cropId" UUID NOT NULL, "weekStart" TIMESTAMP(3) NOT NULL, "weekEnd" TIMESTAMP(3) NOT NULL, "summary" TEXT NOT NULL, "tasks" JSONB NOT NULL, "generatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "WeeklyPlan_pkey" PRIMARY KEY ("id")); CREATE INDEX "WeeklyPlan_cropId_weekStart_idx" ON "WeeklyPlan"("cropId", "weekStart");
CREATE TABLE "Conversation" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "cropId" UUID, "title" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Conversation_pkey" PRIMARY KEY ("id")); CREATE INDEX "Conversation_userId_idx" ON "Conversation"("userId");
CREATE TABLE "Message" ("id" UUID NOT NULL, "conversationId" UUID NOT NULL, "role" "MessageRole" NOT NULL, "content" TEXT NOT NULL, "structuredData" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Message_pkey" PRIMARY KEY ("id")); CREATE INDEX "Message_conversationId_idx" ON "Message"("conversationId");
CREATE TABLE "Notification" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "title" TEXT NOT NULL, "message" TEXT NOT NULL, "readAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Notification_pkey" PRIMARY KEY ("id")); CREATE INDEX "Notification_userId_readAt_idx" ON "Notification"("userId", "readAt");
ALTER TABLE "RefreshToken" ADD CONSTRAINT "RefreshToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Farm" ADD CONSTRAINT "Farm_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Plot" ADD CONSTRAINT "Plot_farmId_fkey" FOREIGN KEY ("farmId") REFERENCES "Farm"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Crop" ADD CONSTRAINT "Crop_plotId_fkey" FOREIGN KEY ("plotId") REFERENCES "Plot"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Diagnosis" ADD CONSTRAINT "Diagnosis_cropId_fkey" FOREIGN KEY ("cropId") REFERENCES "Crop"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Analysis" ADD CONSTRAINT "Analysis_cropId_fkey" FOREIGN KEY ("cropId") REFERENCES "Crop"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Recommendation" ADD CONSTRAINT "Recommendation_cropId_fkey" FOREIGN KEY ("cropId") REFERENCES "Crop"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WeeklyPlan" ADD CONSTRAINT "WeeklyPlan_cropId_fkey" FOREIGN KEY ("cropId") REFERENCES "Crop"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Conversation" ADD CONSTRAINT "Conversation_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Conversation" ADD CONSTRAINT "Conversation_cropId_fkey" FOREIGN KEY ("cropId") REFERENCES "Crop"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Message" ADD CONSTRAINT "Message_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "Conversation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Notification" ADD CONSTRAINT "Notification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
